
use std::collections::HashMap;
use std::fs;
use std::path::{Path, PathBuf};

const PROGRAMS_SUBDIR: &str = "tests/programs";
const OUTPUT_FILE: &str = "generated_program_tests.rs";
const HEADER: &str =
    "// @generated by build.rs — do not edit. One #[test] per tests/programs/*.pluck.\n\n";

pub fn generate(manifest_dir: &Path, out_dir: &Path) {
    let programs_dir = manifest_dir.join(PROGRAMS_SUBDIR);
    crate::rerun_if_changed(&programs_dir);

    let programs = collect_programs(&programs_dir);
    let body = render_tests(&programs);

    let out_path = out_dir.join(OUTPUT_FILE);
    fs::write(&out_path, body)
        .unwrap_or_else(|e| panic!("failed to write {}: {}", out_path.display(), e));
}

fn collect_programs(dir: &Path) -> Vec<PathBuf> {
    let mut programs: Vec<PathBuf> = fs::read_dir(dir)
        .unwrap_or_else(|e| panic!("failed to read {}: {}", dir.display(), e))
        .filter_map(|entry| entry.ok().map(|e| e.path()))
        .filter(|p| p.extension().and_then(|s| s.to_str()) == Some("pluck"))
        .collect();
    programs.sort();
    programs
}

fn render_tests(programs: &[PathBuf]) -> String {
    let mut seen: HashMap<String, usize> = HashMap::new();
    let mut body = String::from(HEADER);

    for path in programs {
        let file_name = path
            .file_name()
            .and_then(|s| s.to_str())
            .unwrap_or_else(|| panic!("non-utf8 filename in {}", path.display()));
        let stem = Path::new(file_name)
            .file_stem()
            .and_then(|s| s.to_str())
            .unwrap_or_else(|| panic!("no stem for {}", file_name));

        let ident = unique_ident(&sanitize(stem), &mut seen);

        body.push_str(&format!(
            "#[test]\nfn program_{ident}() {{\n    run_program_snapshot({file_name:?});\n}}\n\n"
        ));
    }

    body
}

fn sanitize(stem: &str) -> String {
    stem.chars()
        .map(|c| {
            if c.is_ascii_alphanumeric() || c == '_' {
                c.to_ascii_lowercase()
            } else {
                '_'
            }
        })
        .collect()
}

fn unique_ident(base: &str, seen: &mut HashMap<String, usize>) -> String {
    let count = seen.entry(base.to_string()).or_insert(0);
    let ident = if *count == 0 {
        base.to_string()
    } else {
        format!("{}_{}", base, count)
    };
    *count += 1;
    ident
}
